use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::io::{self, Read, Write};

const DIRS: [&str; 6] = ["n", "s", "e", "w", "u", "d"];

#[derive(Clone, PartialEq)]
enum Loc {
    Room(String),
    Inside(String),
    Carried,
}

#[derive(Clone)]
struct Item {
    weight: u64,
    cap: Option<u64>,
    open: bool,
    loc: Loc,
}

#[derive(Clone)]
struct Exit {
    to: String,
    key: Option<String>,
    locked: bool,
}

struct Game {
    rooms: BTreeSet<String>,
    exits: HashMap<(String, usize), Exit>,
    items: BTreeMap<String, Item>,
    player: Option<(String, u64)>,
}

type Res = Result<String, String>;

fn err(msg: &str) -> Res {
    Err(format!("error: {}", msg))
}

fn num(s: &str) -> Option<u64> {
    if s.is_empty() || s.len() > 6 || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse().ok()
}

fn dir_index(d: &str) -> Option<usize> {
    DIRS.iter().position(|x| *x == d)
}

fn here(cur: &str) -> Loc {
    Loc::Room(cur.to_string())
}

fn is_box(items: &BTreeMap<String, Item>, name: &str) -> bool {
    items.get(name).map_or(false, |i| i.cap.is_some())
}

fn at(items: &BTreeMap<String, Item>, name: &str, loc: &Loc) -> bool {
    items.get(name).map_or(false, |i| &i.loc == loc)
}

fn visible(items: &BTreeMap<String, Item>, name: &str, cur: &str) -> bool {
    at(items, name, &here(cur)) || at(items, name, &Loc::Carried)
}

fn children(items: &BTreeMap<String, Item>, name: &str) -> Vec<String> {
    items
        .iter()
        .filter(|(_, i)| matches!(&i.loc, Loc::Inside(p) if p == name))
        .map(|(n, _)| n.clone())
        .collect()
}

fn total(items: &BTreeMap<String, Item>, name: &str) -> u64 {
    let own = items.get(name).map_or(0, |i| i.weight);
    own + children(items, name)
        .iter()
        .map(|c| total(items, c))
        .sum::<u64>()
}

fn render(items: &BTreeMap<String, Item>, name: &str) -> String {
    let it = &items[name];
    if it.cap.is_none() {
        return name.to_string();
    }
    if !it.open {
        return format!("{}{{closed}}", name);
    }
    let parts: Vec<String> = children(items, name)
        .iter()
        .map(|c| render(items, c))
        .collect();
    format!("{}{{{}}}", name, parts.join(", "))
}

fn carried_weight(items: &BTreeMap<String, Item>) -> u64 {
    items
        .keys()
        .filter(|n| at(items, n.as_str(), &Loc::Carried))
        .map(|n| total(items, n.as_str()))
        .sum()
}

fn names_at(items: &BTreeMap<String, Item>, loc: &Loc) -> Vec<String> {
    items
        .keys()
        .filter(|n| at(items, n.as_str(), loc))
        .cloned()
        .collect()
}

fn is_inside_of(items: &BTreeMap<String, Item>, b: &str, x: &str) -> bool {
    let mut cur = b;
    loop {
        if cur == x {
            return true;
        }
        match items.get(cur) {
            Some(Item {
                loc: Loc::Inside(p),
                ..
            }) => cur = p.as_str(),
            _ => return false,
        }
    }
}

fn is_carried_deep(items: &BTreeMap<String, Item>, name: &str) -> bool {
    let mut cur = name;
    loop {
        match items.get(cur) {
            None => return false,
            Some(it) => match &it.loc {
                Loc::Carried => return true,
                Loc::Room(_) => return false,
                Loc::Inside(p) => cur = p.as_str(),
            },
        }
    }
}

fn set_loc(g: &mut Game, name: &str, loc: Loc) {
    g.items.get_mut(name).unwrap().loc = loc;
}

fn parse_loc(g: &Game, s: &str) -> Option<Loc> {
    if let Some(b) = s.strip_prefix("in:") {
        if is_box(&g.items, b) {
            Some(Loc::Inside(b.to_string()))
        } else {
            None
        }
    } else if g.rooms.contains(s) {
        Some(here(s))
    } else {
        None
    }
}

fn world_line(g: &mut Game, t: &[&str]) -> bool {
    match t {
        ["room", name] => {
            if g.rooms.contains(*name) {
                return false;
            }
            g.rooms.insert(name.to_string());
            true
        }
        ["exit", from, d, to, rest @ ..] if rest.len() <= 1 => {
            let di = match dir_index(d) {
                Some(i) => i,
                None => return false,
            };
            if !g.rooms.contains(*from) || !g.rooms.contains(*to) {
                return false;
            }
            let k = (from.to_string(), di);
            if g.exits.contains_key(&k) {
                return false;
            }
            let key = rest.first().map(|k| k.to_string());
            let locked = key.is_some();
            g.exits.insert(
                k,
                Exit {
                    to: to.to_string(),
                    key,
                    locked,
                },
            );
            true
        }
        ["thing", name, w, loc] => {
            let weight = match num(w) {
                Some(n) => n,
                None => return false,
            };
            if g.items.contains_key(*name) {
                return false;
            }
            let loc = match parse_loc(g, loc) {
                Some(l) => l,
                None => return false,
            };
            g.items.insert(
                name.to_string(),
                Item {
                    weight,
                    cap: None,
                    open: false,
                    loc,
                },
            );
            true
        }
        ["box", name, w, cap, loc, rest @ ..]
            if rest.len() <= 1 && rest.iter().all(|r| *r == "open") =>
        {
            let weight = match num(w) {
                Some(n) => n,
                None => return false,
            };
            let cap = match num(cap) {
                Some(n) => n,
                None => return false,
            };
            if g.items.contains_key(*name) {
                return false;
            }
            let loc = match parse_loc(g, loc) {
                Some(l) => l,
                None => return false,
            };
            g.items.insert(
                name.to_string(),
                Item {
                    weight,
                    cap: Some(cap),
                    open: rest.len() == 1,
                    loc,
                },
            );
            true
        }
        ["player", room, lim] => {
            if g.player.is_some() || !g.rooms.contains(*room) {
                return false;
            }
            let limit = match num(lim) {
                Some(n) => n,
                None => return false,
            };
            g.player = Some((room.to_string(), limit));
            true
        }
        _ => false,
    }
}

fn look(g: &Game) -> String {
    let (cur, _) = g.player.as_ref().unwrap();
    let mut lines = vec![format!("== {} ==", cur)];
    let ex: Vec<String> = (0..6)
        .filter_map(|i| {
            g.exits.get(&(cur.clone(), i)).map(|e| {
                if e.locked {
                    format!("{}(locked)", DIRS[i])
                } else {
                    DIRS[i].to_string()
                }
            })
        })
        .collect();
    lines.push(if ex.is_empty() {
        "exits: none".to_string()
    } else {
        format!("exits: {}", ex.join(" "))
    });
    let rendered: Vec<String> = names_at(&g.items, &here(cur))
        .iter()
        .map(|n| render(&g.items, n))
        .collect();
    lines.push(if rendered.is_empty() {
        "items: nothing".to_string()
    } else {
        format!("items: {}", rendered.join(", "))
    });
    lines.join("\n")
}

fn inv(g: &Game) -> String {
    let (_, limit) = g.player.as_ref().unwrap();
    let rendered: Vec<String> = names_at(&g.items, &Loc::Carried)
        .iter()
        .map(|n| render(&g.items, n))
        .collect();
    let body = if rendered.is_empty() {
        "nothing".to_string()
    } else {
        rendered.join(", ")
    };
    format!(
        "carrying: {} ({}/{})",
        body,
        carried_weight(&g.items),
        limit
    )
}

fn go(g: &mut Game, i: usize) -> Res {
    let cur = g.player.as_ref().unwrap().0.clone();
    let (to, locked) = match g.exits.get(&(cur, i)) {
        None => return err(&format!("no exit {}", DIRS[i])),
        Some(e) => (e.to.clone(), e.locked),
    };
    if locked {
        return err(&format!("door {} is locked", DIRS[i]));
    }
    g.player.as_mut().unwrap().0 = to.clone();
    Ok(format!("-> {}", to))
}

fn take(g: &mut Game, x: &str) -> Res {
    let (cur, limit) = g.player.clone().unwrap();
    if !at(&g.items, x, &here(&cur)) {
        return err(&format!("no {} here", x));
    }
    if carried_weight(&g.items) + total(&g.items, x) > limit {
        return err("too heavy");
    }
    set_loc(g, x, Loc::Carried);
    Ok(format!("taken {}", x))
}

fn drop_item(g: &mut Game, x: &str) -> Res {
    let cur = g.player.as_ref().unwrap().0.clone();
    if !at(&g.items, x, &Loc::Carried) {
        return err(&format!("not carrying {}", x));
    }
    set_loc(g, x, here(&cur));
    Ok(format!("dropped {}", x))
}

fn put(g: &mut Game, x: &str, b: &str) -> Res {
    let (cur, limit) = g.player.clone().unwrap();
    if !visible(&g.items, x, &cur) {
        return err(&format!("no {} here", x));
    }
    if !visible(&g.items, b, &cur) {
        return err(&format!("no {} here", b));
    }
    if !is_box(&g.items, b) {
        return err(&format!("{} is not a box", b));
    }
    if is_inside_of(&g.items, b, x) {
        return err(&format!("cannot put {} in itself", x));
    }
    let (open, cap) = {
        let it = &g.items[b];
        (it.open, it.cap.unwrap_or(0))
    };
    if !open {
        return err(&format!("{} is closed", b));
    }
    let w = total(&g.items, x);
    let contents: u64 = children(&g.items, b)
        .iter()
        .map(|c| total(&g.items, c))
        .sum();
    if contents + w > cap {
        return err(&format!("{} is full", b));
    }
    if at(&g.items, b, &Loc::Carried)
        && at(&g.items, x, &here(&cur))
        && carried_weight(&g.items) + w > limit
    {
        return err("too heavy");
    }
    set_loc(g, x, Loc::Inside(b.to_string()));
    Ok(format!("put {} in {}", x, b))
}

fn take_from(g: &mut Game, x: &str, b: &str) -> Res {
    let (cur, limit) = g.player.clone().unwrap();
    if !visible(&g.items, b, &cur) {
        return err(&format!("no {} here", b));
    }
    if !is_box(&g.items, b) {
        return err(&format!("{} is not a box", b));
    }
    let open = g.items[b].open;
    if !open {
        return err(&format!("{} is closed", b));
    }
    if !at(&g.items, x, &Loc::Inside(b.to_string())) {
        return err(&format!("{} is not in {}", x, b));
    }
    if at(&g.items, b, &here(&cur)) && carried_weight(&g.items) + total(&g.items, x) > limit {
        return err("too heavy");
    }
    set_loc(g, x, Loc::Carried);
    Ok(format!("taken {} from {}", x, b))
}

fn set_open(g: &mut Game, b: &str, want: bool) -> Res {
    let cur = g.player.as_ref().unwrap().0.clone();
    if !visible(&g.items, b, &cur) {
        return err(&format!("no {} here", b));
    }
    if !is_box(&g.items, b) {
        return err(&format!("{} is not a box", b));
    }
    if g.items[b].open == want {
        return err(&format!(
            "{} is already {}",
            b,
            if want { "open" } else { "closed" }
        ));
    }
    g.items.get_mut(b).unwrap().open = want;
    Ok(format!("{} {}", if want { "opened" } else { "closed" }, b))
}

fn unlock(g: &mut Game, i: usize) -> Res {
    let cur = g.player.as_ref().unwrap().0.clone();
    let (key, locked) = match g.exits.get(&(cur.clone(), i)) {
        None => return err(&format!("no exit {}", DIRS[i])),
        Some(e) => (e.key.clone().unwrap_or_default(), e.locked),
    };
    if !locked {
        return err(&format!("{} is not locked", DIRS[i]));
    }
    if !(g.items.contains_key(&key) && is_carried_deep(&g.items, &key)) {
        return err(&format!("need {}", key));
    }
    g.exits.get_mut(&(cur, i)).unwrap().locked = false;
    Ok(format!("unlocked {}", DIRS[i]))
}

fn run(g: &mut Game, t: &[&str]) -> Res {
    match t {
        ["look"] => Ok(look(g)),
        ["inv"] => Ok(inv(g)),
        ["go", d] => match dir_index(d) {
            Some(i) => go(g, i),
            None => err("bad command"),
        },
        ["take", x] => take(g, x),
        ["drop", x] => drop_item(g, x),
        ["put", x, "in", b] => put(g, x, b),
        ["take", x, "from", b] => take_from(g, x, b),
        ["open", b] => set_open(g, b, true),
        ["close", b] => set_open(g, b, false),
        ["unlock", d] => match dir_index(d) {
            Some(i) => unlock(g, i),
            None => err("bad command"),
        },
        _ => err("bad command"),
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let all: Vec<&str> = input.lines().collect();
    let sep = all.iter().position(|l| l.trim() == "---");
    let (world, cmds): (&[&str], &[&str]) = match sep {
        Some(p) => (&all[..p], &all[p + 1..]),
        None => (&all[..], &[]),
    };

    let mut g = Game {
        rooms: BTreeSet::new(),
        exits: HashMap::new(),
        items: BTreeMap::new(),
        player: None,
    };
    let mut out = String::new();
    let mut failed = false;

    for (i, line) in world.iter().enumerate() {
        let t: Vec<&str> = line.split_whitespace().collect();
        if t.is_empty() {
            continue;
        }
        if !world_line(&mut g, &t) {
            out += &format!("error: bad world line {}\n", i + 1);
            failed = true;
        }
    }

    if g.player.is_none() {
        out += "error: no player\n";
        print!("{}", out);
        io::stdout().flush().unwrap();
        std::process::exit(1);
    }

    for line in cmds {
        let t: Vec<&str> = line.split_whitespace().collect();
        if t.is_empty() {
            continue;
        }
        let msg = match run(&mut g, &t) {
            Ok(s) => s,
            Err(s) => {
                failed = true;
                s
            }
        };
        out += &msg;
        out.push('\n');
    }

    print!("{}", out);
    io::stdout().flush().unwrap();
    std::process::exit(if failed { 1 } else { 0 });
}

